WITH enriched AS (SELECT *, CORR(quantity, unit_price) OVER (PARTITION BY product_id) AS corr_quantity_unit_price, NTILE(10) OVER (ORDER BY unit_price DESC, id) AS unit_price_bucket FROM order_items), enriched_order_items AS (SELECT *, LEAD(unit_price_bucket, 2, 0) OVER (PARTITION BY order_id ORDER BY quantity, id) AS next_unit_price_bucket, CUME_DIST() OVER (PARTITION BY order_id, product_id ORDER BY unit_price DESC NULLS FIRST) AS unit_price_cume_dist FROM enriched), with_windows AS (SELECT *, CUME_DIST() OVER (PARTITION BY order_id ORDER BY next_unit_price_bucket NULLS LAST) AS next_unit_price_bucket_cume_dist, AVG(next_unit_price_bucket) OVER (ORDER BY unit_price_cume_dist, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS next_unit_price_bucket_avg_3, LEAD(quantity, 1, 0) OVER (PARTITION BY product_id ORDER BY unit_price_cume_dist, id) AS next_quantity FROM enriched_order_items), base AS (SELECT *, quantity * next_unit_price_bucket_cume_dist AS quantity_times_next_unit_price_bucket_cume_dist FROM with_windows WHERE product_id IS NOT NULL AND next_unit_price_bucket = 7), metrics AS (SELECT *, NTILE(4) OVER (PARTITION BY product_id ORDER BY next_unit_price_bucket_cume_dist DESC, id) AS next_unit_price_bucket_cume_dist_bucket, NTILE(5) OVER (PARTITION BY order_id ORDER BY next_unit_price_bucket_cume_dist DESC, id) AS next_unit_price_bucket_cume_dist_bucket_2, ROW_NUMBER() OVER w_recent AS event_seq, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY unit_price_cume_dist DESC, id) AS seq_no FROM base WINDOW w_recent AS (PARTITION BY order_id, product_id ORDER BY next_unit_price_bucket DESC, id)), with_windows_order_items AS (SELECT *, LAST_VALUE(quantity_times_next_unit_price_bucket_cume_dist, TRUE) OVER (PARTITION BY product_id ORDER BY next_unit_price_bucket_avg_3, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_quantity_times_next_unit_price_bucket_cume_dist, SUM(next_unit_price_bucket_cume_dist) OVER (PARTITION BY product_id ORDER BY next_unit_price_bucket_avg_3, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_next_unit_price_bucket_cume_dist FROM metrics) SELECT * FROM (SELECT id, product_id, corr_quantity_unit_price, next_unit_price_bucket_cume_dist, last_known_quantity_times_next_unit_price_bucket_cume_dist FROM with_windows_order_items) src UNPIVOT (val FOR metric_name IN (corr_quantity_unit_price, next_unit_price_bucket_cume_dist, last_known_quantity_times_next_unit_price_bucket_cume_dist))
